// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy, Bank} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.roll(uint256(uint160(actor)));

        // Caller 1: a Bank whose first airdrop succeeds, gaining a balance of 20.
        BankCaller first = new BankCaller(c);
        first.drop(); // succeeds on both P and M

        // Caller 2: a Bank that already holds a balance -> its airDrop REVERTS
        // (hasNoBalance). On P the lock is released afterwards; on M it stays set.
        SelfStuck second = new SelfStuck(c);
        try second.poke() { /* should not happen */ } catch { /* expected revert */ }

        // Caller 3: a fresh eligible Bank caller. The reference always lets it
        // succeed; the buggy version reverts because the lock was never released.
        BankCaller third = new BankCaller(c);
        bool ok;
        try third.drop() { ok = true; } catch { ok = false; }

        // General rule: after any settled airDrop attempts, a fresh eligible
        // caller's airDrop succeeds (lock released). Reading c's actual behavior:
        assertTrue(ok && c.tokenBalance(address(third)) == 20);
    }
}

contract BankCaller is Bank {
    ModifierEntrancy c;
    constructor(ModifierEntrancy _c) { c = _c; }
    function drop() external { c.airDrop(); }
}

contract SelfStuck is Bank {
    ModifierEntrancy c;
    constructor(ModifierEntrancy _c) { c = _c; }
    function poke() external { c.airDrop(); }
}
